fits={p:[i for i,q in enumerate(Qs) if embeds(p,q)] for p in Qs}
def pattern(nodes, adj):
 seen=set();out=[];nu=0
 for v in nodes:
  if v in seen:continue
  if len(adj[v])>2:return None
  if not adj[v]:continue
  todo=[v];seen.add(v);verts=[];degs=0
